<?php require_once __DIR__.'/../inc/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method Not Allowed');}verify_csrf();$id=max(0,(int)($_POST['id']??0));$q=db()->prepare('SELECT profile_picture FROM students WHERE id=?');$q->execute([$id]);$s=$q->fetch();if(!$s){flash('error','الطالب غير موجود.');redirect('/students/index.php');}$q=db()->prepare('DELETE FROM students WHERE id=?');$q->execute([$id]);delete_picture($s['profile_picture']);flash('success','تم حذف الطالب.');redirect('/students/index.php');